class game_info
{
protected:
  int difficulty;
  stringx hero_name_0;
  stringx hero_name_1;
public:
  bool set_str(const pstring &att, const stringx &val);
};

bool game_info::set_str(const pstring &att, const stringx &val)
{
  { static pstring pstring_set("HERO_NAME_0"); if(att == pstring_set) { hero_name_0 = val; return(true); } }
  { static pstring pstring_set("HERO_NAME_1"); if(att == pstring_set) { hero_name_1 = val; return(true); } }
  return(false);
}
